body {
    margin: 0;
    padding: 0;
    background: #f7f7f5;
    color: #333;
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 15px;
    line-height: 1.5;
}

#page {
    max-width: 960px;
    margin: 2em auto;
    padding: 0 1.5em 2em;
}

h1 {
    font-size: 1.8em;
    margin-bottom: 0.3em;
    border-bottom: 1px solid #ddd;
    padding-bottom: 0.3em;
}

h2 {
    font-size: 1.2em;
    margin: 0 0 0.6em;
}

.hint {
    color: #666;
}

textarea {
    box-sizing: border-box;
    width: 100%;
    padding: 0.6em;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-family: Consolas, "Liberation Mono", Menlo, monospace;
    font-size: 13px;
    background: #fff;
}

textarea:focus {
    border-color: #6a9ecf;
    outline: none;
}

#char-counter {
    margin: 0.4em 0;
    color: #888;
    font-size: 0.85em;
    text-align: right;
}

#controls {
    margin: 0.6em 0 1.2em;
}

#controls label {
    margin-right: 0.4em;
}

#controls select,
#controls input[type="submit"],
#controls button {
    padding: 0.35em 0.9em;
    border: 1px solid #bbb;
    border-radius: 4px;
    background: #fff;
    font-size: 0.95em;
    cursor: pointer;
}

#controls input[type="submit"] {
    background: #4a7fb5;
    border-color: #3d6a99;
    color: #fff;
