    box-sizing: border-box;
    width: 49%;
    padding: 1em;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: #fff;
}

.column.kept {
    border-top: 3px solid #5a9955;
    margin-right: 2%;
}

.column.removed {
    border-top: 3px solid #c0504d;
}

.column ul {
    margin: 0;
    padding-left: 1.3em;
}

.column li {
    margin-bottom: 0.6em;
}

.column li.empty {
    color: #999;
    font-style: italic;
    list-style: none;
}

.error {
    color: #c0504d;
    border: 1px solid #c0504d;
    border-radius: 4px;
    padding: 0.6em 1em;
    background: #fdf3f2;
}

